create function operations_private.hub_output_ownership_v1(p_field text,p_scope text) returns jsonb language sql immutable set search_path=pg_catalog as $$
 select jsonb_build_object('stage',case when p_field='actual_inbound_cost' then 'inbound_cost' when p_field='platform_discount_price' then 'seller_discount' when p_field like 'platform_%' then 'seller_price' else p_field end,'output_field',p_field,'scope',coalesce(p_scope,''),'exclusive_group',coalesce(nullif(p_scope,''),'common')||':'||p_field)
$$;
revoke all on function operations_private.hub_output_ownership_v1(text,text) from public,anon,authenticated;
create function public.hub_product_tag_metadata_update_v1(p_session_token text,p_tag_id uuid,p_name text,p_color text default null,p_expected_name text default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog set statement_timeout='30s' set lock_timeout='5s' as $$
declare actor jsonb; before_tag public.product_tags%rowtype; result public.product_tags%rowtype;
begin
 actor:=operations_private.require_operations_hub_operator_session(p_session_token);
 if p_tag_id is null or coalesce(length(btrim(p_name)),0) not between 1 and 200 or p_color is not null and p_color !~ '^#[0-9a-fA-F]{6}$' then raise exception '태그 이름/색상 오류';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-rule-registry',0));
 select * into before_tag from public.product_tags where tag_id=p_tag_id and is_active for update;
 if not found then raise exception '활성 태그를 찾지 못했습니다.';end if;
 if p_expected_name is not null and before_tag.tag_name is distinct from p_expected_name then raise exception '태그 이름이 외부에서 변경됐습니다. 다시 조회하세요.';end if;
 if exists(select 1 from public.product_tags where is_active and tag_id<>p_tag_id and lower(btrim(tag_name))=lower(btrim(p_name))) then raise exception '같은 이름의 활성 태그가 있습니다.';end if;
 if before_tag.tag_name=btrim(p_name) and (p_color is null or p_color=before_tag.tag_color) then return to_jsonb(before_tag);end if;
 update public.product_tags set tag_name=btrim(p_name),tag_color=coalesce(p_color,tag_color),updated_at=clock_timestamp() where tag_id=p_tag_id returning * into result;
 insert into operations_private.hub_rule_events(action,before_value,after_value,actor) values('tag_metadata_update',to_jsonb(before_tag),to_jsonb(result),actor->>'username');
 return to_jsonb(result);
end $$;
create function public.hub_product_tag_rename_v1(p_session_token text,p_tag_id uuid,p_name text,p_expected_name text default null)
returns jsonb language sql set search_path=pg_catalog as $$
 select public.hub_product_tag_metadata_update_v1(p_session_token,p_tag_id,p_name,null,p_expected_name)
$$;
revoke all on function public.hub_product_tag_metadata_update_v1(text,uuid,text,text,text) from public;
revoke all on function public.hub_product_tag_rename_v1(text,uuid,text,text) from public;
grant execute on function public.hub_product_tag_metadata_update_v1(text,uuid,text,text,text) to anon,authenticated;
grant execute on function public.hub_product_tag_rename_v1(text,uuid,text,text) to anon,authenticated;
CREATE OR REPLACE FUNCTION operations_private.hub_sync_tag_rules(p_skus text[], p_actor text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare collision text; changed integer; removed integer; conflict_details text;
begin
 perform pg_advisory_xact_lock(hashtextextended('hub-rule-registry',0));
 if exists(select 1 from pg_class where oid=to_regclass('pg_temp.hub_desired_tag_rules') and relowner<>current_user::regrole) then raise exception '임시 계산 테이블 소유권 오류';end if;
 create temporary table if not exists hub_desired_tag_rules(sku text,rule_id uuid,target_field text,scope text,tag_id uuid,input_origin text) on commit drop;
 create index if not exists hub_desired_tag_rules_lookup on pg_temp.hub_desired_tag_rules(sku,target_field,scope,rule_id);
 truncate pg_temp.hub_desired_tag_rules;
 insert into pg_temp.hub_desired_tag_rules
 select distinct a.sellpia_sku_code,r.id,r.target_field,r.scope,r.tag_id,r.input_origin
 from public.sellpia_tag_assignments a join operations_private.hub_rules r on r.tag_id=a.tag_id and r.is_active
 where a.is_active and a.tag_scope='option' and a.sellpia_sku_code in(select unnest(p_skus))
 union
 select distinct p.sellpia_sku_code,r.id,r.target_field,r.scope,r.tag_id,r.input_origin
 from public.sellpia_stock_latest p
 join public.sellpia_tag_assignments a on a.is_active and a.tag_scope='product' and a.sellpia_product_code=p.sellpia_product_code
 join operations_private.hub_rules r on r.tag_id=a.tag_id and r.is_active
 where p.sellpia_sku_code in(select unnest(p_skus));
 analyze pg_temp.hub_desired_tag_rules;
 select string_agg(format('%s · %s %s · %s',c.sku,coalesce(nullif(c.scope,''),'공통'),c.target_field,c.names),'; ') into conflict_details from (
  select d.sku,d.scope,d.target_field,string_agg(distinct coalesce(t.tag_name,r.name)||' [Rule '||r.name||']',', ') names
  from pg_temp.hub_desired_tag_rules d join operations_private.hub_rules r on r.id=d.rule_id left join public.product_tags t on t.tag_id=d.tag_id
  group by d.sku,d.scope,d.target_field having count(distinct d.rule_id)>1 order by d.sku,d.scope,d.target_field limit 20
 ) c;
 if conflict_details is not null then raise exception '같은 출력의 수식 태그 충돌: %. 기존 적용을 유지하고 전체 요청을 취소했습니다.',conflict_details;end if;
 select string_agg(format('%s · %s %s · 기존 Rule %s / 요청 Rule %s',c.sku,coalesce(nullif(c.scope,''),'공통'),c.target_field,c.old_name,c.new_name),'; ') into conflict_details from (
  select distinct d.sku,d.scope,d.target_field,old.name old_name,new.name new_name
  from pg_temp.hub_desired_tag_rules d join operations_private.hub_rule_assignments a using(sku,target_field,scope)
  join operations_private.hub_rules old on old.id=a.rule_id join operations_private.hub_rules new on new.id=d.rule_id
  where a.rule_id<>d.rule_id and (a.assigned_tag_id is null or exists(select 1 from pg_temp.hub_desired_tag_rules keep where keep.sku=a.sku and keep.rule_id=a.rule_id))
  order by d.sku,d.scope,d.target_field limit 20
 ) c;
 if conflict_details is not null then raise exception '같은 출력의 기존 Rule 충돌: %. 기존 적용을 유지하고 전체 요청을 취소했습니다.',conflict_details;end if;
 select d.sku into collision from pg_temp.hub_desired_tag_rules d where d.input_origin='parent' and not exists(select 1 from operations_private.hub_field_references f where f.child_sku=d.sku and f.rule_id=d.rule_id) limit 1;
 if collision is not null then raise exception '%: 상위 SKU를 참조하는 수식은 종속관계를 먼저 연결하세요.',collision;end if;
 delete from operations_private.hub_rule_assignments a where a.sku in(select unnest(p_skus)) and a.assigned_tag_id is not null and not exists(select 1 from pg_temp.hub_desired_tag_rules d where d.sku=a.sku and d.rule_id=a.rule_id);
 get diagnostics removed=row_count;
 insert into operations_private.hub_rule_assignments(sku,rule_id,target_field,scope,assigned_tag_id,updated_by)
 select d.sku,d.rule_id,d.target_field,d.scope,d.tag_id,p_actor from pg_temp.hub_desired_tag_rules d
 where not exists(select 1 from operations_private.hub_rule_assignments a where a.sku=d.sku and a.target_field=d.target_field and a.scope=d.scope)
 on conflict(sku,target_field,scope) do nothing;
 get diagnostics changed=row_count;
 if changed+removed>0 then perform operations_private.hub_validate_rule_graph();end if;
 return changed;
end $function$
;
CREATE OR REPLACE FUNCTION public.hub_calculation_results_read_v1(p_session_token text, p_skus text[], p_scope text DEFAULT NULL::text, p_fields text[] DEFAULT NULL::text[], p_after_key jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare result jsonb;
begin
 perform operations_private.require_operations_hub_operator_session(p_session_token);
 if coalesce(cardinality(p_skus),0) not between 1 and 1000 or p_limit is null or p_limit not between 1 and 1000 then raise exception '계산 결과 조회는 요청당 SKU 1~1,000개, 결과 최대 1,000개입니다.';end if;
 if p_scope is not null and p_scope not in ('','smartstore','makeshop','ably') then raise exception '판매처 범위 오류';end if;
 if p_fields is not null and cardinality(p_fields)>16 then raise exception '조회 필드가 너무 많습니다.';end if;
 if p_after_key is not null and (jsonb_typeof(p_after_key) is distinct from 'object' or p_after_key->>'sku' is null or p_after_key->>'scope' is null or p_after_key->>'field' is null) then raise exception '계산 결과 페이지 키 오류';end if;
 with matching_keys as materialized(
  select r.sku,r.scope,r.field from operations_private.hub_calculated_results r
  where r.sku in(select distinct unnest(p_skus)) and (p_scope is null or r.scope=p_scope) and (p_fields is null or r.field=any(p_fields))
 ), page as materialized(
  select r.* from operations_private.hub_calculated_results r join matching_keys k using(sku,scope,field)
  where p_after_key is null or (r.sku,r.scope,r.field)>(p_after_key->>'sku',p_after_key->>'scope',p_after_key->>'field')
  order by r.sku,r.scope,r.field limit p_limit+1
 ), visible as materialized(select * from page order by sku,scope,field limit p_limit), identities as materialized(
  select m.sellpia_sku_code,m.smartstore_product_code,m.smartstore_option_code,m.makeshop_product_code,m.makeshop_option_code,m.ably_product_code,m.ably_option_code
  from operations_private.operations_hub_matrix_export_cache m where m.sellpia_sku_code in(select sku from visible where scope<>'' union select unnest(p_skus) where p_scope in ('smartstore','makeshop','ably'))
 ), resolved as (
  select v.*,case v.scope when 'smartstore' then m.smartstore_product_code when 'makeshop' then m.makeshop_product_code when 'ably' then m.ably_product_code end seller_product_code,
   case v.scope when 'smartstore' then m.smartstore_option_code when 'makeshop' then m.makeshop_option_code when 'ably' then m.ably_option_code end seller_option_code
  from visible v left join identities m on m.sellpia_sku_code=v.sku
 ), missing as (
  select m.sellpia_sku_code,p_scope source_channel,
   case p_scope when 'smartstore' then m.smartstore_product_code when 'makeshop' then m.makeshop_product_code when 'ably' then m.ably_product_code end seller_product_code,
   case p_scope when 'smartstore' then m.smartstore_option_code when 'makeshop' then m.makeshop_option_code when 'ably' then m.ably_option_code end seller_option_code,
   '계산 결과 오류 또는 누락: '||string_agg(f.field,', ' order by f.field) reason
  from identities m cross join unnest(coalesce(p_fields,array['platform_registration_price','platform_discount_price','platform_option_price','platform_final_price'])) f(field)
  where p_scope in ('smartstore','makeshop','ably') and m.sellpia_sku_code in(select unnest(p_skus))
   and nullif(btrim(case p_scope when 'smartstore' then m.smartstore_product_code when 'makeshop' then m.makeshop_product_code when 'ably' then m.ably_product_code end),'') is not null
   and not exists(select 1 from operations_private.hub_calculated_results r where r.sku=m.sellpia_sku_code and r.scope=p_scope and r.field=f.field and r.status='calculated')
  group by m.sellpia_sku_code,m.smartstore_product_code,m.smartstore_option_code,m.makeshop_product_code,m.makeshop_option_code,m.ably_product_code,m.ably_option_code
 )
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(v)||jsonb_build_object('mapping_missing',v.scope<>'' and nullif(btrim(v.seller_product_code),'') is null,
  'active_output_rules',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'tag_id',r.tag_id,'tag_name',t.tag_name)||operations_private.hub_output_ownership_v1(r.target_field,r.scope))
   from operations_private.hub_rule_assignments a join operations_private.hub_rules r on r.id=a.rule_id left join public.product_tags t on t.tag_id=r.tag_id
   where a.sku=v.sku and a.target_field=v.field and a.scope=v.scope and r.is_active and r.target_field=a.target_field and r.scope=a.scope and (r.tag_id is null or t.is_active)),'[]'::jsonb)) order by sku,scope,field) from resolved v),'[]'),
  'total',(select count(*) from matching_keys),
  'missing_skus',coalesce((select jsonb_agg(s order by s) from (select distinct unnest(p_skus) s) requested where not exists(select 1 from matching_keys k where k.sku=requested.s)),'[]'),
  'missing',coalesce((select jsonb_agg(to_jsonb(m) order by sellpia_sku_code) from missing m),'[]'),
  'next_key',case when (select count(*) from page)>p_limit then (select jsonb_build_object('sku',sku,'scope',scope,'field',field) from visible order by sku desc,scope desc,field desc limit 1) else null end)
 into result;
 return result;
end $function$
;
CREATE OR REPLACE FUNCTION public.hub_tag_catalog_v1(p_session_token text, p_search text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '30s'
AS $function$
declare
 actor jsonb;
 result jsonb;
begin
 actor:=operations_private.require_operations_hub_operator_session(p_session_token);

 select coalesce(jsonb_agg(to_jsonb(row_data) order by lower(row_data.tag_name),row_data.tag_name),'[]'::jsonb)
 into result
 from (
  select
   t.tag_id,
   t.tag_name,
   t.tag_color,
   t.tag_group,
   (select coalesce(jsonb_agg(jsonb_build_object('rule_id',r.id,'rule_name',r.name)||operations_private.hub_output_ownership_v1(r.target_field,r.scope)),'[]'::jsonb) from operations_private.hub_rules r where r.is_active and r.tag_id=t.tag_id) as outputs,
   count(a.assignment_id) filter(where a.is_active and a.tag_scope='option')::integer as option_count,
   count(a.assignment_id) filter(where a.is_active and a.tag_scope='product')::integer as product_count,
   (
    select count(*)::integer
    from operations_private.hub_rules r
    where r.is_active and r.tag_id=t.tag_id
   ) as rule_count
  from public.product_tags t
  left join public.sellpia_tag_assignments a on a.tag_id=t.tag_id
  where t.is_active
    and (btrim(coalesce(p_search,''))='' or t.tag_name ilike '%'||btrim(p_search)||'%')
  group by t.tag_id,t.tag_name,t.tag_color,t.tag_group
 ) row_data;

 return jsonb_build_object('rows',result);
end $function$
;
notify pgrst,'reload schema';
